#pragma once
#include <Arduino.h>
#include <vector>

// Violet binary packet ("trame") encoding, as parsed by the original
// bootcode (chor/trame.mtl, main.mtl) and generated by OpenJabNab
// (server/lib/*packet.cpp, choregraphy.cpp).
//
//   trame  = 0x7F  { type(1) len(3, big-endian) data(len) }  0xFF
//   type 0x04 ambient : 7F FF FF FE  { service(1) value(1) }
//   type 0x0A message : 0x00 + obfuscated "KEY value\n..." program
//   type 0x0B sleep   : 1 byte, 0 = wake up, 1 = sleep
namespace packets {

using Bytes = std::vector<uint8_t>;

enum Service : uint8_t {
    SVC_DISABLE = 0,
    SVC_WEATHER = 1,
    SVC_STOCK = 2,
    SVC_PERIPH = 3,
    SVC_LEFT_EAR = 4,
    SVC_RIGHT_EAR = 5,
    SVC_EMAIL = 6,
    SVC_AIR = 7,
    SVC_NOSE = 8,
    SVC_BOTTOM = 9,
    SVC_TAICHI = 0x0E,
};

struct Block {
    uint8_t type;
    Bytes data;
};

Bytes trame(const std::vector<Block> &blocks);
Block ambient(const std::vector<std::pair<uint8_t, uint8_t>> &services);
Block message(const String &program);
Block sleep(bool sleep);

// Choreography file (fetched by the rabbit via a "CH <url>" program line).
//   len(4) 00 01 tempo { delay(1) opcode args... } 00 00 00 00
class Chor {
   public:
    explicit Chor(uint8_t tempo10ms = 10);  // frame duration in 10 ms units
    // LED ids follow OpenJabNab: 0 bottom, 1 left, 2 middle, 3 right, 4 top (nose)
    Chor &led(uint8_t delay, uint8_t led, uint8_t r, uint8_t g, uint8_t b);
    Chor &ledOff(uint8_t delay, uint8_t led);
    Chor &allLeds(uint8_t delay, uint8_t r, uint8_t g, uint8_t b);  // opcode 9 (bootcode v16+)
    // ear 0 = left, 1 = right; pos 0..16; dir 0 = forward, 1 = backward
    Chor &motor(uint8_t delay, uint8_t ear, uint8_t pos, uint8_t dir);
    Bytes build() const;

   private:
    Bytes body;
};

String base64(const Bytes &b);
String hex(const Bytes &b);
bool fromHex(const String &s, Bytes &out);

}  // namespace packets
